        var result = listMemberLoansUseCase.listActiveLoans(new ListMemberLoansQuery(memberId, page, size));
        return MemberLoansResponse.of(result, page, size);
    }

    // 반납한 대출을 포함한 전체 대출 이력. 대출일 최신순이며 대출한 적이 없으면 빈 배열이다
    @GetMapping("/{memberId}/loans/history")
    public List<LoanHistoryResponse> listLoanHistory(@PathVariable UUID memberId) {
        return listMemberLoanHistoryUseCase.listLoanHistory(memberId).stream()
                .map(LoanHistoryResponse::from)
                .toList();
    }
}
