package com.example.lending;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.util.Map;
import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class MemberSuspensionIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void new_member_is_not_suspended() throws Exception {
        String memberId = registerMember();

        mockMvc.perform(get("/members/{memberId}", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.suspended").value(false));
    }

    @Test
    void suspending_and_unsuspending_a_member_returns_200_and_updates_state() throws Exception {
        String memberId = registerMember();

        mockMvc.perform(post("/members/{memberId}/suspend", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.suspended").value(true));
        mockMvc.perform(get("/members/{memberId}", memberId))
                .andExpect(jsonPath("$.suspended").value(true));

        mockMvc.perform(post("/members/{memberId}/unsuspend", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.suspended").value(false));
        mockMvc.perform(get("/members/{memberId}", memberId))
                .andExpect(jsonPath("$.suspended").value(false));
    }

    @Test
    void suspending_an_already_suspended_member_returns_200() throws Exception {
        String memberId = registerMember();

        mockMvc.perform(post("/members/{memberId}/suspend", memberId)).andExpect(status().isOk());
        mockMvc.perform(post("/members/{memberId}/suspend", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.suspended").value(true));
    }

    @Test
    void suspending_or_unsuspending_an_unknown_member_returns_404() throws Exception {
        String unknownId = UUID.randomUUID().toString();

        mockMvc.perform(post("/members/{memberId}/suspend", unknownId))
                .andExpect(status().isNotFound());
        mockMvc.perform(post("/members/{memberId}/unsuspend", unknownId))
                .andExpect(status().isNotFound());
    }

    @Test
    void suspended_member_loan_request_returns_409_with_member_suspended_error() throws Exception {
        String memberId = registerMember();
        String bookId = registerBook();
        mockMvc.perform(post("/members/{memberId}/suspend", memberId)).andExpect(status().isOk());

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(loanBody(bookId, memberId)))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("MEMBER_SUSPENDED"));
    }

    @Test
    void member_can_loan_again_after_unsuspend() throws Exception {
        String memberId = registerMember();
        String bookId = registerBook();
        mockMvc.perform(post("/members/{memberId}/suspend", memberId)).andExpect(status().isOk());
        mockMvc.perform(post("/members/{memberId}/unsuspend", memberId)).andExpect(status().isOk());

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(loanBody(bookId, memberId)))
                .andExpect(status().isCreated());
    }

    @Test
    void suspended_member_loan_is_rejected_before_book_state_is_checked() throws Exception {
        String memberId = registerMember();
        String bookId = registerBook();
        mockMvc.perform(post("/members/{memberId}/suspend", memberId)).andExpect(status().isOk());

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(loanBody(bookId, memberId)))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("MEMBER_SUSPENDED"));
        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(loanBody(bookId, memberId)))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("MEMBER_SUSPENDED"));
    }

    private String registerMember() throws Exception {
        String response = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"정지테스트\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(response).get("memberId").asText();
    }

    private String registerBook() throws Exception {
        String response = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"Clean Architecture\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        JsonNode book = objectMapper.readTree(response);
        return book.get("id").asText();
    }

    private String loanBody(String bookId, String memberId) throws Exception {
        return objectMapper.writeValueAsString(Map.of("bookId", bookId, "memberId", memberId));
    }
}

